func HealthRoute() chi.Router {
	hh := handler.HealthHandler{}
	hr := chi.NewRouter()
	hr.Get("/ping", hh.PingHandler)
	hr.Head("/healthcheck", hh.HealthCheckHandler)
	return hr
}

func SetupRoute() chi.Router {
	mR := chi.NewRouter()
	mR.Mount("/", HealthRoute())
	return mR
}

package handler

import (
	"encoding/json"
	"net/http"
)

type HealthHandler struct{}

func (hh *HealthHandler) PingHandler(w http.ResponseWriter, r *http.Request) {
	json.NewEncoder(w).Encode(map[string]string{"message": "pong"})
}

func (hh *HealthHandler) HealthCheckHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusNoContent)
}

